params.frameCode:
scatter = scatter * 0.88;
beatPulse = beatPulse * 0.82;
timeAccum = timeAccum + 0.02 + $BASS * 0.05 + scatter * 0.08;
r = 1.0;
g = 1.0;
b = 1.0;
a = 1.0;

params.pointCode:
seed1 = sin(i * 91.345 + timeAccum * 2.0);
seed2 = cos(i * 157.891 + timeAccum * 1.5);
speed = 0.4 + (i * 0.6);
fall = (timeAccum * speed + i) % 1.0;
baseX = seed1 * 0.95;
baseY = 1.0 - (fall * 2.1);
scatterX = sin(i * 314.159) * scatter * 0.4;
scatterY = cos(i * 271.828) * scatter * 0.4;
x = clamp(baseX + scatterX, -0.98, 0.98);
y = clamp(baseY + scatterY, -0.98, 0.98);
linesize = 12.0 + (v * 16.0) + ($BASS * 24.0) + (scatter * 32.0);
